window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a25dc338f45c68bb"]={"versions": [{"id": "FIG-a25dc338f45c68bb", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle) : Std_ReturnType</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle) : Std_ReturnType</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}, {"id": "FIG-de55b97524d394bd", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}, {"id": "FIG-07ad884a41283428", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}, {"id": "FIG-aa80bdfeb5784e04", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}, {"id": "FIG-74b14af6700d8d88", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}, {"id": "FIG-af516f1e69b3f4d5", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerkmanagement-Modul (<code>Nm</code>) und dem FlexRay-spezifischen Netzwerkmanagement (<code>FrNm</code>) innerhalb der AUTOSAR-Classic-Platform-Kommunikationsarchitektur (Services Layer). Dargestellt wird die Zustands- und Modusabfolge während der Anforderung und Freigabe des Netzwerks (Normal Operation Sequence).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Beteiligte Instanzen / Lebenslinien:</li>\n<li><code>«module» Nm</code> (AUTOSAR Generic Network Management Interface)</li>\n<li><code>«module» FrNm</code> (AUTOSAR FlexRay Network Management)</li>\n<li>Synchrone Aufrufe (durchgezogene Pfeile mit Rückkehrpfeilen):</li>\n<li><code>FrNm_NetworkRequest(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRequest()</code></li>\n<li><code>FrNm_NetworkRelease(NetworkHandle)</code> / Rückgabepfeil <code>FrNm_NetworkRelease()</code></li>\n<li><code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> / Rückgabepfeil <code>Nm_StateChangeNotification()</code></li>\n<li>Modus- und Zustandsannotationen entlang der <code>FrNm</code>-Lebenslinie:</li>\n<li><code>Bus Sleep Mode</code> / <code>Network Released</code></li>\n<li><code>Synchronize Mode</code></li>\n<li><code>Network Mode</code> / <code>Network Requested</code> / <code>Normal Operation State</code></li>\n<li><code>Repeat Message State</code> / <code>Network Requested</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgangszustand: Das FrNm-Modul befindet sich im Modus <code>Bus Sleep Mode</code> mit Zustand <code>Network Released</code>.</li>\n<li>Das Modul <code>Nm</code> ruft synchron <code>FrNm_NetworkRequest(NetworkHandle)</code> auf, welches mit Rückgabewert zurückkehrt.</li>\n<li>Durch die Anforderung wechselt <code>FrNm</code> in den Modus <code>Synchronize Mode</code>.</li>\n<li><code>FrNm</code> benachrichtigt <code>Nm</code> über den ersten Zustandsübergang mittels synchronem Aufruf von <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n<li>Nach erfolgreicher Synchronisation erfolgt der Übergang in den <code>Network Mode</code> in den Zustand <code>Normal Operation State</code> (<code>Network Requested</code>).</li>\n<li><code>FrNm</code> meldet diese Zustandsänderung erneut über <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code> an <code>Nm</code>.</li>\n<li><code>Nm</code> ruft synchron <code>FrNm_NetworkRelease(NetworkHandle)</code> auf, um das Netzwerk freizugeben.</li>\n<li>Nach der Freigabe wechselt <code>FrNm</code> in den Zustand <code>Repeat Message State</code> (weiterhin im Modus <code>Network Mode</code>, Status <code>Network Requested</code>).</li>\n<li><code>FrNm</code> informiert <code>Nm</code> über diesen Zustandsübergang per <code>Nm_StateChangeNotification(nmNetworkHandle, nmPreviousState, nmCurrentState)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Sequenz verdeutlicht das Zusammenspiel zwischen synchronen Steuerbefehlen von <code>Nm</code> an <code>FrNm</code> und den entsprechenden asynchronen bzw. ereignisgetriebenen Rückmeldungen des Zustandswechsels via <code>Nm_StateChangeNotification</code>.</li>\n<li>Bei Aufruf von <code>FrNm_NetworkRequest</code> bzw. <code>FrNm_NetworkRelease</code> wird nicht unmittelbar der finale Zustand erreicht; die tatsächlichen Phasen- und Moduswechsel (wie Synchronisation auf den FlexRay-Zyklus und Übergang in <code>Normal Operation</code> bzw. Wiedereintritt in <code>Repeat Message</code>) werden durch separate Callbacks signalisiert.</li>\n<li>Integratoren müssen sicherstellen, dass die Callback-Funktion <code>Nm_StateChangeNotification</code> reentrant bzw. blockierungsfrei implementiert ist, um den Ablauf der FrNm-Zustandsmaschine nicht zu verzögern.</li>\n</ul>"}], "trans": [{"from": "FIG-a25dc338f45c68bb", "to": "FIG-de55b97524d394bd", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Schnittstellenaufrufe <code>FrNm_NetworkRequest</code> und <code>FrNm_NetworkRelease</code>: Entfernung der expliziten Rückgabetyp-Signatur (<code> : Std_ReturnType</code>) am Aufrufpfeil.</li>\n<li>Layout/Typografie: Anpassung von vertikalen und horizontalen Textpositionierungen und Abständen.</li>\n</ul>"}, {"from": "FIG-de55b97524d394bd", "to": "FIG-07ad884a41283428", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07ad884a41283428", "to": "FIG-aa80bdfeb5784e04", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aa80bdfeb5784e04", "to": "FIG-74b14af6700d8d88", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-74b14af6700d8d88", "to": "FIG-af516f1e69b3f4d5", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
